//! Arare programs compiled at build time (AR-LLR-025).
//!
//! Quality level QL-B: this crate is the compiled route's output for the
//! programs in `programs.txt`, held to the reference interpreter by the
//! translation validation in `tests/` (AR-VER-220) and timed by the
//! benchmarks (`rust/bench/`, AR-VER-221). Its code is generated by
//! `build.rs`; nothing here is written by hand but this file.

pub use arare_codegen::rt::{Arg, Codes, Column, Out, RunError};

/// A compiled program.
pub struct Program {
    pub name: &'static str,
    pub signature: &'static str,
    pub source: &'static str,
    /// The compiled program: the fast path, or the interpreter when it does
    /// not apply.
    pub run: fn(&[Arg]) -> Result<Vec<Out>, RunError>,
    /// The fast path alone: `None` where it does not apply.
    pub fast: fn(&[Arg]) -> Option<Vec<Out>>,
}

/// The generated code, one function per program and its fast path.
pub mod generated {
    use super::Program;
    include!(concat!(env!("OUT_DIR"), "/compiled.rs"));
}

pub use generated::PROGRAMS;

/// The compiled program of this name.
pub fn program(name: &str) -> Option<&'static Program> {
    PROGRAMS.iter().find(|p| p.name == name)
}
